  set qt = $get(%session.Data("QueryType"))
  set compNm = $get(%session.Data("Component"))
  set nmsp = $get(%session.Data("Namespace"))
  set env = $get(%session.Data("Environment"))

  set sql=""
 if (qt = "C")
 {
	 set sql= "select  c.ComponentName, ci.ClassName, ci.ClassExportFileVersion, i.ImplFileVersion as DeployVersion, i.ImplementionDate, "
	 _ " n.NameSpace, e.Environment, i.ImplFileInformation "

 _ " from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.Namespaces n, "
 _ " IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e,"
 _ " IHC_ITF_SrcCtrlPkg.ClassItem ci "
 _ " where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID "
 _ " and i.ImplFile = ci.ClassExportFile and ci.importDate = i.ImplementionDate "
 }
 else
 {
 set sql="select c.ComponentName, e.Environment, n.NameSpace, i.ImplFileVersion, i.ImplementionDate,"
 _ "  $EXTRACT(i.ImplFile, $FIND( i.ImplFile, 'trunk/'), 250) As DeployFileName , "
   _ "  i.ImplFileInformation"
  _ " from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.Namespaces n, "
  _ " IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e " 
  _ " where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID"
 }
  if (compNm '= "")
 {
  set sql= sql _ " AND c.ComponentName = '" _compNm _ "'"
 }
 if (nmsp '= "")
 {
  set sql= sql _ " AND n.NameSpace = '" _ nmsp _ "'"
 }
 if (env '= "")
 {
  set sql= sql _ " AND e.Environment = '" _env _ "'"
 }
 set sql= sql _ " ORDER BY i.ImplementionDate DESC"
  Set tRS = ##class(%ResultSet).%New()
    Set tSC = tRS.Prepare(sql)
    Set pInfo.queryText = sql

    Quit tRS


	set retStr = "Info: "
	For I=1:1:$L(Selectedfiles,",")
	{
		Set compNm = $P(Selectedfiles,",",I)

		if ( compNm '= "")
		{

	 		&sql(select c.ComponentName, e.Environment, n.NameSpace, i.ImplFileVersion, i.ImplementionDate,
    			 i.ImplFile, i.ImplFileInformation
    			 INTO :cNm, :env, :nmsp, :implFlVer, :implDt, :implFl, :implFlInfo
  				 from IHC_ITF_SrcCtrlPkg.Component c,  IHC_ITF_SrcCtrlPkg.Namespaces n,
  				 IHC_ITF_SrcCtrlPkg.ComponentImpl i, IHC_ITF_SrcCtrlPkg.Environment e  
 				  where c.NameSpace = n.ID and c.ID = i.ComponentName and i.Environment = e.ID
 				 AND c.ComponentName = :compNm)

 			 IF SQLCODE = 0 
 			{ 
	  		 	set retStr = retStr _", "_ env _", "_nmsp _", "_implFlVer _", "_implDt _", "_implFl _", "_implFlInfo
	 		}
	 		else
	 		{
		 		set retStr = retStr _ compNm _ ": " _ SQLCODE
	 		}
		}
  }
  return retStr
